{
  "title": "Tính diện tích hình elip (E) cắt bởi mặt phẳng (α) và hình trụ",
  "description": "Chương trình này dựng hình trụ và mặt phẳng cắt, sau đó tính diện tích của thiết diện elip.",
  "memory_declarations": [
    {
      "name": "O",
      "type": "point3",
      "initial_value": [0, 0, 0],
      "source_fact_id": "cylinder_definition"
    },
    {
      "name": "K",
      "type": "point3",
      "initial_value": [0, 0, 24],
      "source_fact_id": "cylinder_definition"
    },
    {
      "name": "A",
      "type": "point3",
      "initial_value": [5, 0, 0],
      "source_fact_id": "point_a_on_base"
    },
    {
      "name": "E",
      "type": "ellipse3"
    },
    {
      "name": "dien_tich_elip_e",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "construct_curved_solid",
      "target_var": "hinh_tru",
      "curved_kind": "cylinder",
      "anchor": "O",
      "apex_or_top": "K",
      "rim_point": "A",
      "label": "Hình trụ"
    },
    {
      "kind": "construct_plane_from_equation",
      "target_var": "mat_phang_alpha",
      "a": 2,
      "b": 0,
      "c": -1,
      "d": 12,
      "source_fact_id": "plane_alpha_equation",
      "label": "Mặt phẳng alpha"
    },
    {
      "kind": "assign",
      "target_var": "E",
      "expr": {
        "kind": "intersect_plane_curved_ellipse",
        "solid": "hinh_tru",
        "plane": "mat_phang_alpha"
      }
    },
    {
      "kind": "assign",
      "target_var": "dien_tich_elip_e",
      "expr": {
        "kind": "measure",
        "quantity": "area",
        "of": "E"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách xác định và tính diện tích thiết diện elip khi một mặt phẳng cắt xiên hình trụ."
}
